import { useClipPathObserver, usePrevious } from '@/hub/hooks';
import { useApplications } from '@/hub/hooks/store/applications';
import { useIsEmbeddedPanelView } from '@/hub/hooks/store/hub/useIsEmbeddedPanelView';
import { actions as applicationsActions } from '@/store/applications/applicationsState.slice';
import { UI } from '@deprecated/types';
import { Button, ThemeAppLogo } from '@getvim/atomic-ui';
import { useTheme } from '@getvim/components-hooks-use-theme';
import classNames from 'classnames';
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useStore } from 'react-redux';
import { HubMenuIcon } from '../../molecules';
import './index.less';
import { APPS_MENU_ELEMENT_ID } from './appsMenu.consts';
export interface AppsMenuProps {
  /**
   * Is the menu active - controls if it's semi-expanded by default
   */
  active?: boolean;
  notifications?: number;
  loading?: boolean;
  selectedAppId?: string;
  hubPosition: UI.HubPosition;
  moveAppMenu: (direction: UI.HubDirection) => void;
  onClose: () => void;
  onMenuShrinkChange?: (isShrinked: boolean) => void;
  onHubIconHover?: () => void;
  clearNotificationsIndicator?: boolean;
  showMicrophoneBadge?: boolean;
  showErrorPopover?: boolean;
}

export const AppsMenu: React.FC<React.PropsWithChildren<AppsMenuProps>> = ({
  active,
  hubPosition,
  moveAppMenu,
  selectedAppId,
  notifications,
  loading,
  onMenuShrinkChange,
  onHubIconHover,
  onClose,
  children,
  clearNotificationsIndicator,
  showMicrophoneBadge = false,
  showErrorPopover = false,
}) => {
  const showFlatView = useIsEmbeddedPanelView();

  const [shrink, setShrink] = useState(true);
  const wasShrink = usePrevious(shrink);
  const { showExpandedHeader } = useTheme();
  const { dispatch } = useStore();
  const expanded = showFlatView || active || !shrink || selectedAppId || showErrorPopover;
  const shrinkTimeoutRef = React.useRef<NodeJS.Timeout | null>(null);
  const isHubPositionUpperLimit = hubPosition.vertical === UI.VerticalHubPosition.High;
  const isHubPositionLowerLimit = hubPosition.vertical === UI.VerticalHubPosition.Low;
  const isHubPositionLeft = hubPosition.horizontal === UI.HorizontalHubPosition.Left;
  const applications = useApplications();

  const appsWithNewBadge = useMemo(() => {
    return Object.values(applications).filter((app) => app.addedManuallyNow);
  }, [applications]);

  useEffect(() => {
    if (showFlatView) {
      setShrink(false);
    }
  }, [showFlatView]);
  useEffect(() => {
    let timer;
    if (appsWithNewBadge.length > 0) {
      timer = setTimeout(() => {
        dispatch(applicationsActions.turnOffNewAppBadge(appsWithNewBadge.map((app) => app.id)));
      }, 10_000);
    }

    return () => timer && clearTimeout(timer);
  }, [appsWithNewBadge, dispatch]);

  const changeShrink = useCallback(
    (newVal: boolean) => {
      if (showFlatView) {
        return;
      }
      if (selectedAppId) {
        return;
      }
      // Allow expansion on hover when there's an error, even if hub is not active
      if (showErrorPopover && newVal === false) {
        setShrink(false);
        return;
      }
      // Only allow shrinking if there's no error or if we're explicitly shrinking
      if (!showErrorPopover || newVal === true) {
        setShrink(newVal);
      }
    },
    [selectedAppId, showErrorPopover, showFlatView],
  );

  useEffect(() => {
    if (wasShrink !== undefined && shrink !== wasShrink) {
      onMenuShrinkChange?.(shrink);
    }
  }, [onMenuShrinkChange, shrink, wasShrink]);

  const handleMouseLeave = useCallback(() => {
    // Only apply timeout when there's an error popover to prevent flickering
    if (showErrorPopover) {
      shrinkTimeoutRef.current = setTimeout(() => {
        changeShrink(true);
      }, 300);
    } else {
      changeShrink(true);
    }
  }, [changeShrink, showErrorPopover]);

  const handleMouseEnter = useCallback(() => {
    if (shrinkTimeoutRef.current) {
      clearTimeout(shrinkTimeoutRef.current);
      shrinkTimeoutRef.current = null;
    }
    changeShrink(false);
  }, [changeShrink]);

  const onSelectedAppClose = useCallback(() => {
    onClose();
  }, [onClose]);

  useEffect(() => {
    if (!selectedAppId && !showErrorPopover) {
      changeShrink(true);
    }
  }, [selectedAppId, changeShrink, showErrorPopover]);

  const onHubMenuMouseEnter = useCallback(() => {
    handleMouseEnter();
    onHubIconHover?.();
  }, [handleMouseEnter, onHubIconHover]);

  const onUpClick = useCallback(() => {
    moveAppMenu({ vertical: UI.VerticalDirection.Up });
  }, [moveAppMenu]);

  const onDownClick = useCallback(() => {
    moveAppMenu({ vertical: UI.VerticalDirection.Down });
  }, [moveAppMenu]);

  const onOppositeDirectionClick = useCallback(() => {
    moveAppMenu(
      isHubPositionLeft
        ? { horizontal: UI.HorizontalDirection.Right }
        : { horizontal: UI.HorizontalDirection.Left },
    );
  }, [moveAppMenu, isHubPositionLeft]);

  const componentToObserveRef = useClipPathObserver();
  const sideArrowToObserveRef = useClipPathObserver();

  return (
    <div
      ref={componentToObserveRef}
      id={APPS_MENU_ELEMENT_ID}
      className={classNames('apps-menu', {
        'hub-positioned-left': isHubPositionLeft,
        'selected-mode': selectedAppId,
        'top-120': showFlatView ? false : showExpandedHeader,
        'top-75': showFlatView ? false : !showExpandedHeader,
        'flat-view': showFlatView,
        'rounded-none': showFlatView,
      })}
    >
      {!expanded ? (
        <HubMenuIcon
          notifications={notifications}
          ignoreNotificationsValue={shrink}
          shrink={showFlatView ? false : showErrorPopover ? shrink : true}
          inactive={!active && !loading}
          loading={loading}
          onMouseEnter={onHubMenuMouseEnter}
          clearNotificationsIndicator={clearNotificationsIndicator}
          hubPosition={hubPosition}
          showNewAppBadge={appsWithNewBadge?.length > 0}
          showMicrophoneBadge={showMicrophoneBadge}
        />
      ) : (
        <div
          className={classNames('expanded', {
            '!items-start': showFlatView,
            '!flex-row': showFlatView,
            '!justify-start': showFlatView,
          })}
          onMouseEnter={showFlatView ? undefined : handleMouseEnter}
          onMouseLeave={showFlatView ? undefined : handleMouseLeave}
        >
          {selectedAppId || showFlatView ? (
            <div
              role="none"
              className={classNames('icon-container menu-close')}
              onClick={onSelectedAppClose}
            >
              <ThemeAppLogo className="w-[48px]" />
            </div>
          ) : (
            <>
              <Button
                className={classNames('icon-chevron-up', 'chevron-button', 'up', {
                  disabled: isHubPositionUpperLimit,
                })}
                buttonType="link"
                onClick={onUpClick}
              />
              <div className="expanded-hub-menu-icon-wrapper">
                <HubMenuIcon
                  notifications={shrink ? notifications : 0}
                  inactive={!active && !loading}
                  loading={loading}
                  onMouseEnter={onHubIconHover}
                  clearNotificationsIndicator={clearNotificationsIndicator || !shrink}
                  showNewAppBadge={false}
                  hubPosition={hubPosition}
                  showMicrophoneBadge={showMicrophoneBadge && shrink}
                  showErrorPopover={showErrorPopover}
                />

                <div ref={sideArrowToObserveRef} className="side-arrow-bounding-box-spy"></div>
                <Button
                  data-testid="hub-position-left"
                  className="icon-chevron-left chevron-button side-arrow"
                  buttonType="link"
                  onClick={onOppositeDirectionClick}
                />
              </div>
            </>
          )}

          {(!shrink || selectedAppId) && (
            <div
              className={classNames('applications-menu-icons ', {
                'flex-col': !showFlatView,
                'flex-row': showFlatView,
                '[&>div:last-child]:ml-auto': showFlatView,
                'w-full': showFlatView,
              })}
            >
              {children}
            </div>
          )}
          {!selectedAppId && !showFlatView && (
            <Button
              className={classNames('icon-chevron-down', 'chevron-button', 'down', {
                disabled: isHubPositionLowerLimit,
              })}
              buttonType="link"
              onClick={onDownClick}
            />
          )}
        </div>
      )}
    </div>
  );
};
