import { shallowEqual } from 'react-redux';
import { useAppSelector } from '../hooks';
import { selectUserApplicationIds } from '@/store/selectors/appListening.selectors';

export const useApplications = () => {
  return useAppSelector((state) => state.applicationsState.applications, shallowEqual);
};

export const useUserApplicationIds = () => {
  return useAppSelector(selectUserApplicationIds);
};
